import{_ as n,o as s,c as t,a3 as l}from"./chunks/framework.DxEvSMU4.js";const b=JSON.parse('{"title":"該不該自架決策樹","description":"","frontmatter":{},"headers":[],"relativePath":"decide/should-self-host.md","filePath":"decide/should-self-host.md","lastUpdated":1793029011000}'),e={name:"decide/should-self-host.md"};function i(o,a,d,p,r,h){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="該不該自架決策樹" tabindex="-1">該不該自架決策樹 <a class="header-anchor" href="#該不該自架決策樹" aria-label="Permalink to &quot;該不該自架決策樹&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 本頁為整理者判斷框架, 無外部統計數字; 見頁尾「資料來源」</li></ul></div><p><strong>結論</strong>: 依序回答四個問題即可得到初步方向. 結果是整理者的建議 (信心: 中, 屬推論), 不是唯一答案.</p><h2 id="決策樹" tabindex="-1">決策樹 <a class="header-anchor" href="#決策樹" aria-label="Permalink to &quot;決策樹&quot;">​</a></h2><p>決策樹是一連串是非題, 每一題的答案決定下一題, 最後落到一個建議結果. 從 Q1 開始, 依箭頭往下走即可.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>Q1 資料是否因內部規範或合約, 必須留在自己的環境內?</span></span>
<span class="line"><span> |-- 是 --&gt; Q2</span></span>
<span class="line"><span> |-- 否 --&gt; Q3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q2 有人能每週維運 (安全公告, 備份, 升級)?</span></span>
<span class="line"><span> |-- 是 --&gt; 結果 C: 地端 (從最小組合起步)</span></span>
<span class="line"><span> |-- 否 --&gt; 結果 D: 暫緩, 先補維運人力, 或評估廠商託管的私有部署</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q3 用量是否穩定且偏高 (長期攤提硬體有意義)?</span></span>
<span class="line"><span> |-- 是 --&gt; Q4</span></span>
<span class="line"><span> |-- 否 --&gt; 結果 A: 雲端 API</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Q4 開放權重模型在自己的任務上, 實測是否夠用?</span></span>
<span class="line"><span> |-- 是, 且有人維運 --&gt; 結果 B: 混合 (敏感或高用量任務地端, 其餘雲端)</span></span>
<span class="line"><span> |-- 是, 但沒人維運 --&gt; 結果 A: 雲端 API</span></span>
<span class="line"><span> |-- 否或不確定 --&gt; 結果 D: 先做 30 天 PoC 實測</span></span></code></pre></div><h2 id="各結果的說明" tabindex="-1">各結果的說明 <a class="header-anchor" href="#各結果的說明" aria-label="Permalink to &quot;各結果的說明&quot;">​</a></h2><p>四個結果中, A 是全部使用雲端服務, C 是全部在自己的環境執行, B 介於兩者之間, D 則是先補足條件或先試做再決定. 試做在本手冊稱為 PoC (Proof of Concept, 概念驗證), 指正式投資前的小規模驗證.</p><table tabindex="0"><thead><tr><th>結果</th><th>建議做法</th><th>下一步</th></tr></thead><tbody><tr><td>A 雲端 API</td><td>以企業方案採購, 並確認供應商的資料處理條款</td><td>條款判讀請洽法律顧問</td></tr><tr><td>B 混合</td><td>地端處理敏感或高用量任務, 其餘走雲端; 閘道的需求見 <a href="/lanai-handbook/build/m5-gateway-identity">M5.1 節</a></td><td>先做 PoC, 再決定是否加閘道</td></tr><tr><td>C 地端</td><td>採最小組合起步, 逐步加層</td><td><a href="/lanai-handbook/build/overview">「組裝總覽」</a>與 <a href="/lanai-handbook/know/k6-security">K6</a></td></tr><tr><td>D 暫緩</td><td>補足維運人力, 或先用 PoC 取得實測資料</td><td><a href="/lanai-handbook/decide/poc-30days">30 天 PoC 計畫</a></td></tr></tbody></table><h2 id="使用提醒" tabindex="-1">使用提醒 <a class="header-anchor" href="#使用提醒" aria-label="Permalink to &quot;使用提醒&quot;">​</a></h2><ul><li>Q4 的「夠用」應以自己的 20 至 50 題實測判斷, 不以排行榜分數替代 (見 <a href="/lanai-handbook/build/m4-retrieval">M4.3 節</a>與 <a href="/lanai-handbook/build/m6-observability">M6</a>).</li><li>Q2 的「有人維運」指有具名的人, 每週實際執行; 只在組織圖上有職稱不算.</li><li>本決策樹未涵蓋法規與契約細節, Q1 的答案請由法務或資安負責人確認.</li></ul><h2 id="資料來源" tabindex="-1">資料來源 <a class="header-anchor" href="#資料來源" aria-label="Permalink to &quot;資料來源&quot;">​</a></h2><p>本頁為整理者依本手冊 <a href="/lanai-handbook/know/k2-quantization">K2</a>, <a href="/lanai-handbook/know/k6-security">K6</a>, <a href="/lanai-handbook/build/m4-retrieval">M4</a>, <a href="/lanai-handbook/build/m6-observability">M6</a>, <a href="/lanai-handbook/ops/backup">O1 至 O3</a> 與<a href="/lanai-handbook/decide/tco">成本試算表</a>整理的判斷框架, 沒有引用外部決策模型, 市場資料或統計數字.</p><ul><li><strong>決策樹的分支條件與結果 A 至 D</strong>: 資料留存, 維運人力, 用量, 實測是否夠用四個條件是整理者的選擇, 屬推論 (信心: 中). 結論一節已標示此點.</li><li><strong>「20 至 50 題實測」</strong>: 建議題數, 不是來自標準或研究 (推論, 信心: 低). 測試集的設計方法見 <a href="/lanai-handbook/build/m6-observability">M6</a>.</li><li><strong>各結果引用的外部事實</strong> (例如閘道需求, 評測方法, 維運工作): 依據在所連結章節的「參考來源」, 本頁不重複列出.</li><li><strong>法規與契約</strong>: 本頁與本手冊都不含法規解讀, Q1 的答案請由法務或資安負責人確認.</li></ul>`,14)])])}const u=n(e,[["render",i]]);export{b as __pageData,u as default};
